joi_block.script:
currentMode_v = (#Main_Pump).pump_pumpMode
if (currentMode_v == "normal") {
(#Main_Pump).pump_setPumpMode("maximum")
}

brightness_v = (#Bedroom_LightSensor).lightSensor_brightness
if (brightness_v <= 100) {
(#Bedroom_FloorLamp).switch_on()
}
else {
(#Bedroom_FloorLamp).switch_off()
}

t1_v = (#LivingRoom_TempSensor).temperatureSensor_temperature
t2 = (#Bedroom_TempSensor).temperatureSensor_temperature
if (t1_v >= 28 or t2 >= 30) {
(#LivingRoom_AC).switch_on()
}

lux_v = (#LivingRoom_LightSensor).lightSensor_brightness
if (lux_v <= 200) {
(#LivingRoom_Light).light_moveToBrightness(100.0, 0.0)
}
else {
if (lux_v >= 500) {
(#LivingRoom_Light).light_moveToBrightness(30.0, 0.0)
}
else {
(#LivingRoom_Light).light_moveToBrightness(60.0, 0.0)
}
}

livingRoomHumidity_v = (#LivingRoom_HumiditySensor).humiditySensor_humidity
bedroomHumidity = (#Bedroom_HumiditySensor).humiditySensor_humidity
if (livingRoomHumidity_v <= 30 or bedroomHumidity <= 30) {
(#LivingRoom_Humidifier).switch_on()
}

wait until((#Bedroom_MB).multiButton_button1 == "pushed")
current_v = (#Bedroom_Light).light_currentBrightness
if (current_v >= 80) {
(#Bedroom_Light).light_moveToBrightness(10.0, 0.0)
}
else {
(#Bedroom_Light).light_moveToBrightness(80.0, 0.0)
}

t1_v = (#WineCellar_TempSensor).temperatureSensor_temperature
delay(1 HOUR)
t2 = (#WineCellar_TempSensor).temperatureSensor_temperature
if (t2 - t1_v >= 2) {
(#LivingRoom_Speaker).speaker_speak("The wine cellar temperature rose by at least 2 degrees.")
}

phase_v := 0
if (phase_v == 0) {
wait until(all(#ContactSensor).contactSensor_contact ==| false)
    phase_v = 1
    all(#Speaker).speaker_speak("Welcome")
}
else {
all(#Speaker).speaker_speak("Welcome")
}

phase_v := 0
if (phase_v == 0) {
wait until(all(#ContactSensor).contactSensor_contact ==| true)
    phase_v = 1
    all(#Siren).siren_setSirenMode("police")
}
else {
all(#Siren).siren_setSirenMode("police")
}

phase_v := 0
if (phase_v == 0) {
wait until((#Entrance_ContactSensor).contactSensor_contact == false)
    phase_v = 1
    if ((#Main_DoorLock).doorLock_doorLockState != "closed") {
all(#Speaker).speaker_speak("The safe is open")
}
}
else {
if ((#Main_DoorLock).doorLock_doorLockState != "closed") {
all(#Speaker).speaker_speak("The safe is open")
}
}

phase_v := 0
if (phase_v == 0) {
wait until(all(#SmokeDetector).smokeDetector_smoke ==| true)
    phase_v = 1
    all(#Siren).siren_setSirenMode("emergency")
    delay(5 SEC)
all(#Switch).switch_off()
}
else {
all(#Siren).siren_setSirenMode("emergency")
    delay(5 SEC)
all(#Switch).switch_off()
}

phase_v := 0
if (phase_v == 0) {
wait until((#Main_Charger).charger_voltage <= 4000)
    phase_v = 1
    all(#Speaker).speaker_speak("The charging voltage is low")
}
else {
all(#Speaker).speaker_speak("The charging voltage is low")
}

phase_v := 0
if (phase_v == 0) {
wait until((#Main_Fan).fan_speed == 0)
    phase_v = 1
    all(#Speaker).speaker_speak("Please check the fan")
}
else {
all(#Speaker).speaker_speak("Please check the fan")
}

phase_v := 0
if (phase_v == 0) {
wait until(all(#MotionSensor).motionSensor_motion ==| true)
    phase_v = 1
    all(#Camera).camera_captureImage()
}
else {
all(#Camera).camera_captureImage()
}

phase_v := 0
if (phase_v == 0) {
wait until((#P_AQ).airQualitySensor_carbonDioxide > 880)
    phase_v = 1
    (#P_Speaker).speaker_speak("CO2 level danger")
}
else {
(#P_Speaker).speaker_speak("CO2 level danger")
}

phase_v := 0
if (phase_v == 0) {
wait until(all(#PresenceSensor).presenceSensor_presence ==| true)
    phase_v = 1
    (#F1_Siren).siren_setSirenMode("emergency")
    delay(3 SEC)
(#F1_Siren).switch_off()
}
else {
(#F1_Siren).siren_setSirenMode("emergency")
    delay(3 SEC)
(#F1_Siren).switch_off()
}

phase_v := 0
if (phase_v == 0) {
wait until((#Lobby_Mot).motionSensor_motion == true)
    phase_v = 1
    (#Lobby_Cam).camera_captureImage()
}
else {
(#Lobby_Cam).camera_captureImage()
}

phase_v := 0
if (phase_v == 0) {
wait until((#K_Smoke).smokeDetector_smoke == true)
    phase_v = 1
    (#LR_Speaker).speaker_speak("Fire outbreak")
}
else {
(#LR_Speaker).speaker_speak("Fire outbreak")
}

n_v := 0
if (n_v % 2 == 0) {
all(#Valve).valve_open()
}
else {
all(#Valve).valve_close()
}
n_v = n_v + 1

n_v := 0
if (n_v % 2 == 0) {
(#LivingRoom_AirPurifier).airPurifier_setAirPurifierMode("sleep")
}
else {
(#LivingRoom_AirPurifier).airPurifier_setAirPurifierMode("auto")
}
n_v = n_v + 1

n_v := 0
if (n_v % 2 == 0) {
all(#WindowCovering).windowCovering_upOrOpen()
}
else {
all(#WindowCovering).windowCovering_downOrClose()
}
n_v = n_v + 1

n_v := 0
if (n_v % 2 == 0) {
all(#AirPurifier).airPurifier_setAirPurifierMode("sleep")
}
else {
all(#AirPurifier).airPurifier_setAirPurifierMode("high")
}
n_v = n_v + 1

n_v := 0
if (n_v % 2 == 0) {
(#LR_Blind).windowCovering_upOrOpen()
}
else {
(#LR_Blind).windowCovering_downOrClose()
}
n_v = n_v + 1

n_v := 0
if (n_v % 2 == 0) {
(#BR_Win).windowCovering_upOrOpen()
}
else {
(#BR_Win).windowCovering_downOrClose()
}
n_v = n_v + 1

n_v := 0
if (n_v % 2 == 0) {
(#MR_AC).airConditioner_setTargetTemperature(25.0)
}
else {
(#MR_AC).airConditioner_setTargetTemperature(20.0)
}
n_v = n_v + 1

temp_v = (#Living_Temp).temperatureSensor_temperature
if (temp_v >= 20 and temp_v < 30) {
all(#AirConditioner).airConditioner_setAirConditionerMode("auto")
}
else {
if (temp_v >= 30) {
all(#AirConditioner).airConditioner_setAirConditionerMode("cool")
}
}

temp_v = (#Living_Temp).temperatureSensor_temperature
if (temp_v >= 30) {
all(#AirConditioner).airConditioner_setTargetTemperature(25.0)
}
else {
if (temp_v < 23) {
all(#AirConditioner).airConditioner_setTargetTemperature(26.0)
}
}

fd_v = (#Living_AQ).airQualitySensor_fineDustLevel
if (fd_v >= 200) {
all(#AirPurifier).airPurifier_setAirPurifierMode("high")
}
else {
if (fd_v <= 100) {
all(#AirPurifier).airPurifier_setAirPurifierMode("low")
}
}

temp_v = (#Inside_TemperatureSensor).temperatureSensor_temperature
if (temp_v >= 25) {
all(#Switch).switch_on()
all(#AirConditioner).airConditioner_setAirConditionerMode("cool")
}
else {
all(#Switch).switch_off()
}

l1_v = (#LivingRoom_LightSensor).lightSensor_brightness
l2 = (#Bedroom_LightSensor).lightSensor_brightness
if (l1_v <= 100 and l2 <= 100) {
(#LivingRoom_MoodLight).switch_on()
}

living_temp_v = (#LivingRoom_TempSensor).temperatureSensor_temperature
bedroom_temp = (#Bedroom_TempSensor).temperatureSensor_temperature
if (living_temp_v >= 25 and bedroom_temp >= 25) {
(#LivingRoom_Fan).switch_on()
}

n_v := 0
if (n_v >= 10) {
break
}
(#MeetingRoom_Camera).camera_captureImage()
n_v = n_v + 1

n_v := 0
if (n_v >= 4) {
break
}
(#LivingRoom_Light).light_moveToBrightness(100, 0)
n_v = n_v + 1

n_v := 0
if (n_v >= 3) {
break
}
all(#Speaker).speaker_speak("lunch time")
n_v = n_v + 1

n_v := 0
if (n_v >= 6) {
break
}
(#LivingRoom_AC).switch_on()
n_v = n_v + 1

n_v := 0
if (n_v >= 5) {
break
}
all(#Speaker).speaker_speak("meeting reminder")
n_v = n_v + 1

n_v := 0
if (n_v >= 6) {
break
}
all(#Siren).siren_setSirenMode("emergency")
n_v = n_v + 1

n_v := 0
if (n_v >= 5) {
break
}
(#Bedroom_Blind).windowCovering_upOrOpen()
n_v = n_v + 1

n_v := 0
if (n_v >= 4) {
break
}
all(#AirPurifier).airPurifier_setAirPurifierMode("high")
n_v = n_v + 1

n_v := 0
if (n_v >= 3) {
break
}
(#Garage_DoorLock).doorLock_unlock()
n_v = n_v + 1

n_v := 0
if (n_v >= 8) {
break
}
(#Kitchen_Light).light_moveToBrightness(100.0, 0.0)
n_v = n_v + 1

n_v := 0
if (n_v >= 6) {
break
}
v = (#LivingRoom_Temp).temperatureSensor_temperature
if (v >= 28) {
(#LivingRoom_AC).airConditioner_setAirConditionerMode("cool")
}
else {
(#LivingRoom_AC).airConditioner_setAirConditionerMode("auto")
}
n_v = n_v + 1

n_v := 0
if (n_v >= 4) {
break
}
v = (#Bedroom_Temp).temperatureSensor_temperature
if (v < 20) {
(#Bedroom_AC).airConditioner_setAirConditionerMode("heat")
}
else {
(#Bedroom_AC).airConditioner_setAirConditionerMode("auto")
}
n_v = n_v + 1

n_v := 0
if (n_v >= 10) {
break
}
v = (#Server_Temp).temperatureSensor_temperature
if (v >= 30) {
(#Server_AC).airConditioner_setAirConditionerMode("cool")
}
else {
(#Server_AC).airConditioner_setAirConditionerMode("auto")
}
n_v = n_v + 1

n_v := 0
if (n_v >= 5) {
break
}
v = (#Office_Temp).temperatureSensor_temperature
if (v >= 26) {
(#Office_AC).airConditioner_setAirConditionerMode("cool")
}
else {
(#Office_AC).airConditioner_setAirConditionerMode("auto")
}
n_v = n_v + 1

n_v := 0
if (n_v >= 3) {
break
}
v = (#LivingRoom_Temp).temperatureSensor_temperature
if (v < 18) {
(#LivingRoom_AC).airConditioner_setAirConditionerMode("heat")
}
else {
(#LivingRoom_AC).airConditioner_setAirConditionerMode("auto")
}
n_v = n_v + 1
